import{_ as e,o as t,c as r,a2 as l}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"企业邮箱 FAQ","description":"","frontmatter":{"title":"企业邮箱 FAQ"},"headers":[],"relativePath":"ops-knowledge-base/ssl/enterprise-email-faq.md","filePath":"ops-knowledge-base/ssl/enterprise-email-faq.md","lastUpdated":1788259091000}'),i={name:"ops-knowledge-base/ssl/enterprise-email-faq.md"};function n(h,a,d,o,p,s){return t(),r("div",null,[...a[0]||(a[0]=[l('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本文解答 RAKsmart 配套企业邮箱的登录、管理与配置常见问题。</p><h2 id="_1-邮件服务器在国内还是国外" tabindex="-1">1. 邮件服务器在国内还是国外？ <a class="header-anchor" href="#_1-邮件服务器在国内还是国外" aria-label="Permalink to &quot;1. 邮件服务器在国内还是国外？&quot;">​</a></h2><p>服务器节点全球分布：海外访问使用海外节点，国内访问使用国内节点，以保证不同地区的收发速度与稳定性。</p><h2 id="_2-企业邮箱有独立的管理员账号吗" tabindex="-1">2. 企业邮箱有独立的管理员账号吗？ <a class="header-anchor" href="#_2-企业邮箱有独立的管理员账号吗" aria-label="Permalink to &quot;2. 企业邮箱有独立的管理员账号吗？&quot;">​</a></h2><p>有。邮箱开通后，平台会提供管理员账号和密码。</p><ul><li>登录地址：<a href="https://mail.chengmail.cn/" target="_blank" rel="noreferrer">https://mail.chengmail.cn</a></li><li>默认进入用户登录页面</li><li>在「欢迎登录邮箱」右侧点击「切换至管理员登录」</li><li>使用管理员账号登录后台</li></ul><h2 id="_3-忘记企业邮箱管理员密码怎么办" tabindex="-1">3. 忘记企业邮箱管理员密码怎么办？ <a class="header-anchor" href="#_3-忘记企业邮箱管理员密码怎么办" aria-label="Permalink to &quot;3. 忘记企业邮箱管理员密码怎么办？&quot;">​</a></h2><p>管理员密码只能在后台重置，无法自助找回。请通过客户中心提交工单申请重置，并提供域名或邮箱产品订单信息。</p><h2 id="_4-企业邮箱帮助中心" tabindex="-1">4. 企业邮箱帮助中心 <a class="header-anchor" href="#_4-企业邮箱帮助中心" aria-label="Permalink to &quot;4. 企业邮箱帮助中心&quot;">​</a></h2><ul><li><a href="https://mail.chengmail.cn/help/index.php?_m=articleview&amp;_a=view" target="_blank" rel="noreferrer">https://mail.chengmail.cn/help/index.php?_m=articleview&amp;_a=view</a></li><li><a href="https://mail.chengmail.cn/help/index.php?_m=articleview&amp;_a=view&amp;category_id=044f972f81a3be258c2c35e8ae6ee6d8&amp;lang=zh_CN" target="_blank" rel="noreferrer">中文版使用手册</a></li></ul><h2 id="_5-如何配置-smtp-mx、cname、txt-记录如何设置" tabindex="-1">5. 如何配置 SMTP？MX、CNAME、TXT 记录如何设置？ <a class="header-anchor" href="#_5-如何配置-smtp-mx、cname、txt-记录如何设置" aria-label="Permalink to &quot;5. 如何配置 SMTP？MX、CNAME、TXT 记录如何设置？&quot;">​</a></h2><p>登录企业邮箱管理员后台，进入「域名管理」或「邮箱设置」，系统会显示该域名所需的记录，通常包括：</p><table tabindex="0"><thead><tr><th>记录类型</th><th>用途</th></tr></thead><tbody><tr><td>MX</td><td>邮件收发路由</td></tr><tr><td>TXT（SPF）</td><td>防伪造、提升投递成功率</td></tr><tr><td>CNAME</td><td>部分功能所需，以后台显示为准</td></tr><tr><td>SMTP</td><td>发信服务器地址与端口，以后台显示为准</td></tr></tbody></table><p>具体记录值因域名而异，请以管理员后台显示为准。若无法找到，请提交工单并提供域名。</p><h2 id="_6-如何创建和管理员工邮箱" tabindex="-1">6. 如何创建和管理员工邮箱？ <a class="header-anchor" href="#_6-如何创建和管理员工邮箱" aria-label="Permalink to &quot;6. 如何创建和管理员工邮箱？&quot;">​</a></h2><p>使用管理员账号登录 <a href="https://mail.chengmail.cn/" target="_blank" rel="noreferrer">mail.chengmail.cn</a> 后，可在管理后台创建或删除邮箱、分配容量、设置别名与转发。详细步骤见<a href="https://mail.chengmail.cn/help/index.php?_m=articleview&amp;_a=view&amp;category_id=044f972f81a3be258c2c35e8ae6ee6d8&amp;lang=zh_CN" target="_blank" rel="noreferrer">企业邮箱帮助中心</a>。</p><h2 id="_7-需要技术支持" tabindex="-1">7. 需要技术支持 <a class="header-anchor" href="#_7-需要技术支持" aria-label="Permalink to &quot;7. 需要技术支持&quot;">​</a></h2><p>请通过客户中心提交工单，并提供域名、问题描述及已尝试的步骤和截图。</p>',19)])])}const _=e(i,[["render",n]]);export{m as __pageData,_ as default};
